using System; using System.Collections.Generic; using System.Diagnostics; using System.Runtime.CompilerServices;
using WallstopStudios.UnityHelpers.Core.DataStructure;
class Program {
static long sink; static object built;
static void Main(){Run(false);Run(true);} static void Run(bool measured){if(measured)Console.WriteLine("runtime="+Environment.Version.ToString()+" bitness="+(IntPtr.Size*8));foreach(int n in new[]{64,1024})foreach(string shape in new[]{"dense","sparse","lowbits"}){int[] keys=new int[n];var unique=new HashSet<int>();var random=new Random(7329);for(int i=0;i<n;++i){int k=shape=="dense"?i:shape=="lowbits"?i*1024:random.Next();while(!unique.Add(k))k=random.Next();keys[i]=k;}
var baseline=new BaselineIntMap<int>(n);var candidate=new IntMap<int>(n);var dict=new Dictionary<int,int>(n);foreach(int k in keys){baseline.TrySet(k,k);candidate.TrySet(k,k);dict.Add(k,k);}
foreach(string op in new[]{"construct","iterate","hit","miss","insert"}){int loops=Math.Max(1,10000/n);Action[] arms={GetArm(0,op,baseline,candidate,dict,keys,loops),GetArm(1,op,baseline,candidate,dict,keys,loops),GetArm(2,op,baseline,candidate,dict,keys,loops)};if(!measured){for(int warm=0;warm<64;++warm)foreach(var a in arms)a();continue;}foreach(var a in arms)a();
for(int calibration=0;calibration<20;++calibration){bool enough=true;foreach(var a in arms){var timer=Stopwatch.StartNew();a();timer.Stop();if(timer.Elapsed.TotalMilliseconds<25)enough=false;}if(enough)break;loops*=2;arms=new[]{GetArm(0,op,baseline,candidate,dict,keys,loops),GetArm(1,op,baseline,candidate,dict,keys,loops),GetArm(2,op,baseline,candidate,dict,keys,loops)};if(calibration==19)throw new Exception("calibration failed");}
var times=new double[3,21];for(int round=0;round<21;++round)for(int j=0;j<3;++j){int a=(j+round)%3;var sw=Stopwatch.StartNew();arms[a]();sw.Stop();times[a,round]=sw.Elapsed.TotalMilliseconds*1000000/(loops*n);}for(int round=0;round<21;++round)Console.Error.WriteLine(n+","+shape+","+op+","+loops+","+round+","+times[0,round].ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+times[1,round].ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+times[2,round].ToString("R",System.Globalization.CultureInfo.InvariantCulture));Console.Write(n+","+shape+","+op);for(int a=0;a<3;++a){double[] t=new double[21];for(int j=0;j<21;++j)t[j]=times[a,j];Array.Sort(t);Console.Write(","+t[10].ToString("F4",System.Globalization.CultureInfo.InvariantCulture));}Console.WriteLine();}}
if(measured)Console.WriteLine("sink="+sink);}
static Action GetArm(int arm,string op,BaselineIntMap<int> b,IntMap<int> c,Dictionary<int,int>d,int[]keys,int loops){if(op=="construct"){if(arm==0)return ()=>ConstructBaseline(keys,loops);if(arm==1)return ()=>ConstructCandidate(keys,loops);return ()=>ConstructDictionary(keys,loops);}if(op=="iterate"){if(arm==0)return ()=>IterateBaseline(b,loops);if(arm==1)return ()=>IterateCandidate(c,loops);return ()=>IterateDictionary(d,loops);}if(op=="insert"){if(arm==0)return ()=>InsertBaseline(b,keys,loops);if(arm==1)return ()=>InsertCandidate(c,keys,loops);return ()=>InsertDictionary(d,keys,loops);}if(arm==0)return ()=>LookupBaseline(b,keys,loops,op=="miss");if(arm==1)return ()=>LookupCandidate(c,keys,loops,op=="miss");return ()=>LookupDictionary(d,keys,loops,op=="miss");}
[MethodImpl(MethodImplOptions.NoInlining)] static void IterateBaseline(BaselineIntMap<int> m,int loops){long sum=0;for(int r=0;r<loops;++r)foreach(var pair in m)sum+=pair.Key+pair.Value;sink=sum;}
[MethodImpl(MethodImplOptions.NoInlining)] static void LookupBaseline(BaselineIntMap<int> m,int[]keys,int loops,bool miss){long sum=0;for(int r=0;r<loops;++r)foreach(int k in keys){m.TryGet(miss?~k:k,out int v);sum+=v;}sink=sum;}
[MethodImpl(MethodImplOptions.NoInlining)] static void InsertBaseline(BaselineIntMap<int> m,int[]keys,int loops){for(int r=0;r<loops;++r){m.Clear();foreach(int k in keys){m.TrySet(k,k);}}sink=m.Count;}
[MethodImpl(MethodImplOptions.NoInlining)] static void IterateCandidate(IntMap<int> m,int loops){long sum=0;for(int r=0;r<loops;++r)foreach(var pair in m)sum+=pair.Key+pair.Value;sink=sum;}
[MethodImpl(MethodImplOptions.NoInlining)] static void LookupCandidate(IntMap<int> m,int[]keys,int loops,bool miss){long sum=0;for(int r=0;r<loops;++r)foreach(int k in keys){m.TryGet(miss?~k:k,out int v);sum+=v;}sink=sum;}
