[MethodImpl(MethodImplOptions.NoInlining)] static void IterateDictionary(Dictionary<int,int> m,int loops){long sum=0;for(int r=0;r<loops;++r)foreach(var pair in m)sum+=pair.Key+pair.Value;sink=sum;}
[MethodImpl(MethodImplOptions.NoInlining)] static void LookupDictionary(Dictionary<int,int> m,int[]keys,int loops,bool miss){long sum=0;for(int r=0;r<loops;++r)foreach(int k in keys){m.TryGetValue(miss?~k:k,out int v);sum+=v;}sink=sum;}
[MethodImpl(MethodImplOptions.NoInlining)] static void InsertDictionary(Dictionary<int,int> m,int[]keys,int loops){for(int r=0;r<loops;++r){m.Clear();foreach(int k in keys){m[k]=k;}}sink=m.Count;}
[MethodImpl(MethodImplOptions.NoInlining)] static void ConstructBaseline(int[]keys,int loops){for(int r=0;r<loops;++r){var m=new BaselineIntMap<int>(keys.Length);foreach(int k in keys){m.TrySet(k,k);}built=m;sink=m.Count;}}
