[MethodImpl(MethodImplOptions.NoInlining)] static void ConstructDictionary(int[]keys,int loops){for(int r=0;r<loops;++r){var m=new Dictionary<int,int>(keys.Length);foreach(int k in keys){m[k]=k;}built=m;sink=m.Count;}}
